import express from 'express';
import { exec } from 'child_process';
import { promisify } from 'util';
import path from 'path';
import fs from 'fs/promises';

const execAsync = promisify(exec);
const app = express();
app.use(express.json());

// Image processing endpoint - converts uploaded images using ImageMagick
app.post('/api/convert', async (req, res) => {
  const { sourceFile, outputFormat, quality } = req.body;

  // Validate format
  const allowedFormats = ['png', 'jpg', 'webp', 'gif', 'tiff'];
  if (!allowedFormats.includes(outputFormat)) {
    return res.status(400).json({ error: 'Invalid output format' });
  }

  // Validate quality range
  const q = parseInt(quality) || 85;
  if (q < 1 || q > 100) {
    return res.status(400).json({ error: 'Quality must be 1-100' });
  }

  // Construct output filename
  const baseName = path.basename(sourceFile, path.extname(sourceFile));
  const outputFile = `/tmp/converted/${baseName}.${outputFormat}`;

  try {
    await fs.mkdir('/tmp/converted', { recursive: true });

    // Build conversion command
    const cmd = `convert /uploads/${sourceFile} -quality ${q} -strip ${outputFile}`;
    const { stdout, stderr } = await execAsync(cmd, { timeout: 30000 });

    if (stderr && stderr.includes('ERROR')) {
      console.warn(`Conversion warning: ${stderr}`);
    }

    const stats = await fs.stat(outputFile);
    res.json({
      success: true,
      output: outputFile,
      size: stats.size
    });
  } catch (err) {
    console.error(`Conversion failed: ${err.message}`);
    res.status(500).json({ error: 'Conversion failed' });
  }
});

// Thumbnail generation with resize
app.post('/api/thumbnail', async (req, res) => {
  const { sourceFile, width, height } = req.body;

  const w = parseInt(width) || 150;
  const h = parseInt(height) || 150;

  if (w > 1000 || h > 1000) {
    return res.status(400).json({ error: 'Max dimension is 1000px' });
  }

  const outputFile = `/tmp/thumbs/${path.basename(sourceFile)}_${w}x${h}.png`;

  try {
    await fs.mkdir('/tmp/thumbs', { recursive: true });

    const cmd = `convert /uploads/${sourceFile} -resize ${w}x${h} -strip ${outputFile}`;
    const { stdout } = await execAsync(cmd, { timeout: 15000 });

    res.json({ success: true, thumbnail: outputFile });
  } catch (err) {
    res.status(500).json({ error: 'Thumbnail generation failed' });
  }
});

// Health check with system info
app.get('/api/health', async (req, res) => {
  try {
    const { stdout } = await execAsync('convert --version');
    const diskUsage = await execAsync('df -h /tmp');
    res.json({
      status: 'healthy',
      imagemagick: stdout.split('\n')[0],
      disk: diskUsage.stdout
    });
  } catch (err) {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Image service running on :3000'));
